    const { root } = repo('engine-cheap-change')
    const dir = join(root, '.sofar')
    noteEngine(dir, 'e1', '0.26.1')
    expect(noteEngine(dir, 'e1', '0.27.0')).toBe('0.26.1')
    expect(noteEngine(dir, 'e1', '0.27.0')).toBeNull() // and settles again
